/**
 * Kuromoji Tokenizer Wrapper
 * 负责日文分词和假名处理
 */

// kuromoji 通过 manifest content_scripts 加载，作为全局变量
declare const kuromoji: {
  builder(options: { dicPath: string }): {
    build(callback: (err: Error | null, tokenizer: KuromojiTokenizerInstance) => void): void;
  };
};

interface KuromojiTokenizerInstance {
  tokenize(text: string): KuromojiToken[];
}

// Token 接口定义
export interface KuromojiToken {
  word_id: number;
  word_type: string;
  word_position: number;
  surface_form: string;
  pos: string;
  pos_detail_1: string;
  pos_detail_2: string;
  pos_detail_3: string;
  conjugated_type: string;
  conjugated_form: string;
  basic_form: string;
  reading?: string;
  pronunciation?: string;
}

// 词性类型
export type PosType =
  | 'noun'      // 名詞
  | 'verb'      // 動詞
  | 'adjective' // 形容詞
  | 'adverb'    // 副詞
  | 'particle'  // 助詞
  | 'auxiliary' // 助動詞
  | 'conjunction' // 接続詞
  | 'interjection' // 感動詞
  | 'prenoun'   // 連体詞
  | 'symbol'    // 記号
  | 'other';    // その他

// 分词结果（用于假名标注）
export interface AnnotationToken {
  surface: string;      // 原文
  reading: string;      // 平假名读音
  needsRuby: boolean;   // 是否需要标注
  pos: PosType;         // 词性
  posDetail: string;    // 词性详细（原始）
}

// Kuromoji 分词器类型
interface KuromojiTokenizer {
  tokenize(text: string): KuromojiToken[];
}

let tokenizerInstance: KuromojiTokenizer | null = null;
let initPromise: Promise<KuromojiTokenizer> | null = null;

/**
 * 片假名转平假名
 */
function katakanaToHiragana(str: string): string {
  return str.replace(/[\u30A1-\u30F6]/g, (match) => {
    return String.fromCharCode(match.charCodeAt(0) - 0x60);
  });
}

/**
 * 检查字符串是否只包含平假名
 */
function isOnlyHiragana(str: string): boolean {
  return /^[\u3040-\u309F]+$/.test(str);
}

/**
 * 检查字符串是否只包含片假名
 */
function isOnlyKatakana(str: string): boolean {
  return /^[\u30A0-\u30FF]+$/.test(str);
}

/**
 * 检查字符串是否只包含假名（平假名或片假名）
 */
function isOnlyKana(str: string): boolean {
  return /^[\u3040-\u309F\u30A0-\u30FF]+$/.test(str);
}

/**
 * 检查字符串是否包含汉字
 */
function containsKanji(str: string): boolean {
  return /[\u4E00-\u9FFF\u3400-\u4DBF]/.test(str);
}

/**
 * 检查字符串是否只包含英文和数字
 */
function isAlphanumeric(str: string): boolean {
  return /^[a-zA-Z0-9\s]+$/.test(str);
}

/**
 * 检查字符串是否只包含符号
 */
function isOnlySymbols(str: string): boolean {
  // 常见符号、标点
  return /^[\s\p{P}\p{S}]+$/u.test(str);
}

/**
 * 初始化 kuromoji 分词器
 */
export async function initializeTokenizer(dicPath: string): Promise<KuromojiTokenizer> {
  if (tokenizerInstance) {
    return tokenizerInstance;
  }

  if (initPromise) {
    return initPromise;
  }

  // 检查 kuromoji 是否可用
  console.log('[Furigana] Checking kuromoji availability...');
  console.log('[Furigana] typeof kuromoji:', typeof kuromoji);

  if (typeof kuromoji === 'undefined') {
    return Promise.reject(new Error('kuromoji is not loaded. Check if lib/kuromoji.js is included in manifest.json'));
  }

  console.log('[Furigana] kuromoji is available, dicPath:', dicPath);

  initPromise = new Promise((resolve, reject) => {
    try {
      console.log('[Furigana] Building tokenizer...');
      kuromoji.builder({ dicPath }).build((err, tokenizer) => {
        if (err) {
          console.error('[Furigana] Tokenizer build error:', err);
          initPromise = null;
          reject(err);
          return;
        }
        console.log('[Furigana] Tokenizer built successfully');
        tokenizerInstance = tokenizer;
        resolve(tokenizer);
      });
    } catch (e) {
      console.error('[Furigana] Tokenizer build exception:', e);
      initPromise = null;
      reject(e);
    }
  });

  return initPromise;
}

/**
 * 获取分词器实例
 */
export function getTokenizer(): KuromojiTokenizer | null {
  return tokenizerInstance;
}

/**
 * 检查分词器是否已初始化
 */
export function isTokenizerReady(): boolean {
  return tokenizerInstance !== null;
}

/**
 * 将日语词性映射到统一的词性类型
 */
function mapPosType(pos: string): PosType {
  if (pos.startsWith('名詞')) return 'noun';
  if (pos.startsWith('動詞')) return 'verb';
  if (pos.startsWith('形容詞')) return 'adjective';
  if (pos.startsWith('副詞')) return 'adverb';
  if (pos.startsWith('助詞')) return 'particle';
  if (pos.startsWith('助動詞')) return 'auxiliary';
  if (pos.startsWith('接続詞')) return 'conjunction';
  if (pos.startsWith('感動詞')) return 'interjection';
  if (pos.startsWith('連体詞')) return 'prenoun';
  if (pos.startsWith('記号')) return 'symbol';
  return 'other';
}

/**
 * 对文本进行分词并返回带假名标注信息的 token 列表
 */
export function tokenizeForAnnotation(text: string): AnnotationToken[] {
  if (!tokenizerInstance) {
    throw new Error('Tokenizer not initialized');
  }

  const tokens = tokenizerInstance.tokenize(text);
  const result: AnnotationToken[] = [];

  for (const token of tokens) {
    const surface = token.surface_form;
    const reading = token.reading;
    const pos = token.pos;

    // 判断是否需要标注假名
    let needsRuby = false;
    let hiraganaReading = '';

    if (reading) {
      hiraganaReading = katakanaToHiragana(reading);
    }

    // 需要标注的条件：
    // 1. 包含汉字
    // 2. 不是纯假名
    // 3. 不是英文/数字
    // 4. 不是纯符号
    // 5. 有读音且读音与原文不同
    if (
      containsKanji(surface) &&
      !isOnlyKana(surface) &&
      !isAlphanumeric(surface) &&
      !isOnlySymbols(surface) &&
      reading &&
      surface !== hiraganaReading
    ) {
      needsRuby = true;
    }

    result.push({
      surface,
      reading: hiraganaReading,
      needsRuby,
      pos: mapPosType(pos),
      posDetail: pos
    });
  }

  return result;
}

/**
 * 快速检查文本是否包含需要标注的日文内容
 */
export function hasAnnotatableContent(text: string): boolean {
  // 检查是否包含汉字
  return containsKanji(text);
}
